//! `apisip.toml`: the per-folder configuration, generated by `init` and
//! editable by hand.

use std::collections::BTreeMap;
use std::time::Duration;

use serde::{Deserialize, Deserializer, Serialize, Serializer};

pub const CONFIG_FILE: &str = "apisip.toml";

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Config {
    pub source: Source,
    pub destination: Destination,
    #[serde(default)]
    pub streams: Vec<StreamConfig>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Source {
    /// URL or file path of the OpenAPI spec this config was generated from.
    pub spec: String,
    pub base_url: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub auth: Option<AuthConfig>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rate_limit: Option<RateLimit>,
    #[serde(default)]
    pub retry: RetryConfig,
    /// Streams fetched at the same time.
    #[serde(default = "default_concurrency")]
    pub concurrency: usize,
    /// Extra headers sent with every request. Values may use `${VAR}`.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub headers: BTreeMap<String, String>,
}

fn default_concurrency() -> usize {
    4
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum AuthConfig {
    Bearer {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        token: String,
    },
    ApiKey {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        name: String,
        #[serde(rename = "in")]
        location: ApiKeyLocation,
        value: String,
    },
    Basic {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        username: String,
        password: String,
    },
    Oauth2ClientCredentials {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        token_url: String,
        client_id: String,
        client_secret: String,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        scopes: Vec<String>,
    },
}

impl AuthConfig {
    /// Name of the security scheme in the spec, when known.
    pub fn scheme(&self) -> Option<&str> {
        match self {
            AuthConfig::Bearer { scheme, .. }
            | AuthConfig::ApiKey { scheme, .. }
            | AuthConfig::Basic { scheme, .. }
            | AuthConfig::Oauth2ClientCredentials { scheme, .. } => scheme.as_deref(),
        }
    }

    pub fn kind(&self) -> &'static str {
        match self {
            AuthConfig::Bearer { .. } => "bearer",
            AuthConfig::ApiKey { .. } => "api_key",
            AuthConfig::Basic { .. } => "basic",
            AuthConfig::Oauth2ClientCredentials { .. } => "oauth2_client_credentials",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ApiKeyLocation {
    Header,
    Query,
    Cookie,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RateLimit {
    pub max_calls: u32,
    #[serde(with = "duration_str")]
    pub period: Duration,
}

impl RateLimit {
    pub fn per_second(&self) -> f64 {
        self.max_calls as f64 / self.period.as_secs_f64().max(1e-9)
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RetryConfig {
    #[serde(default = "default_max_tries")]
    pub max_tries: u32,
    #[serde(default = "default_max_backoff", with = "duration_str")]
    pub max_backoff: Duration,
    /// The longest one request may spend waiting between its retries,
    /// `Retry-After` included: past it, the run fails at once.
    #[serde(default = "default_max_wait", with = "duration_str")]
    pub max_wait: Duration,
    #[serde(default = "default_on_status")]
    pub on_status: Vec<u16>,
}

fn default_max_tries() -> u32 {
    8
}
fn default_max_backoff() -> Duration {
    Duration::from_secs(60)
}
fn default_max_wait() -> Duration {
    Duration::from_secs(600)
}
/// Answers that may differ on the next try. 501 and 505 do not, nor does
/// any other 4xx: the request itself is wrong. 520 to 524 come from
/// Cloudflare in front of an API.
fn default_on_status() -> Vec<u16> {
    vec![408, 429, 500, 502, 503, 504, 520, 521, 522, 523, 524]
}

impl Default for RetryConfig {
    fn default() -> Self {
        RetryConfig {
            max_tries: default_max_tries(),
            max_backoff: default_max_backoff(),
            max_wait: default_max_wait(),
            on_status: default_on_status(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Destination {
    /// `file://<dir>` (relative to this folder) or `s3://bucket/prefix`.
    #[serde(default = "default_destination")]
    pub url: String,
    #[serde(default)]
    pub format: Format,
    #[serde(default)]
    pub rotate: Rotate,
    /// S3 endpoint for S3-compatible stores; `AWS_ENDPOINT_URL` also works.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub endpoint: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub region: Option<String>,
}

impl Destination {
    /// The destination as the user wrote it, without `file://` or a trailing
    /// slash, to print the paths inside it.
    pub fn shown(&self) -> &str {
        self.url.trim_start_matches("file://").trim_end_matches('/')
    }
}

/// Data goes to `data/` inside the API folder, apart from the config.
pub const DEFAULT_DESTINATION: &str = "file://data";

fn default_destination() -> String {
    DEFAULT_DESTINATION.into()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Format {
    #[default]
    Jsonl,
    Parquet,
}

impl Format {
    pub fn extension(self) -> &'static str {
        match self {
            Format::Jsonl => "jsonl",
            Format::Parquet => "parquet",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Rotate {
    #[serde(with = "bytes_str")]
    pub max_bytes: u64,
}

impl Default for Rotate {
    fn default() -> Self {
        Rotate {
            max_bytes: 128 * 1024 * 1024,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct StreamConfig {
    pub name: String,
    pub path: String,
    #[serde(default = "yes", skip_serializing_if = "is_true")]
    pub enabled: bool,
    /// JSON pointer to the record array in the response body; empty when the body is the array.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub records: String,
    #[serde(
        default,
        skip_serializing_if = "Vec::is_empty",
        serialize_with = "ser_key",
        deserialize_with = "de_key"
    )]
    pub primary_key: Vec<String>,
    /// Fixed query parameters sent with every request.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub params: BTreeMap<String, String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pagination: Option<Pagination>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub incremental: Option<Incremental>,
    /// What to do with a value of the wrong JSON type, in Parquet output.
    #[serde(default, skip_serializing_if = "is_lossless")]
    pub cast: Cast,
}

/// `lossless` converts a value when the conversion keeps it, such as
/// `"007"` to 7 for an integer column; `exact` only when the text prints back
/// the same (`"7"`, not `"007"`); `none` quarantines the record instead.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Cast {
    #[default]
    Lossless,
    Exact,
    None,
}

fn is_lossless(c: &Cast) -> bool {
    *c == Cast::Lossless
}

fn yes() -> bool {
    true
}
fn is_true(b: &bool) -> bool {
    *b
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum Pagination {
    /// `?page=1,2,3…`
    PageNumber {
        param: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size_param: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size: Option<u32>,
        #[serde(default = "one")]
        start: u64,
    },
    /// `?offset=0,100,200…&limit=100`
    Offset {
        param: String,
        limit_param: String,
        limit: u32,
    },
    /// The next request carries a token read from the response body.
    Cursor {
        param: String,
        /// JSON pointer to the next token in the body (e.g. `/meta/next_cursor`).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        cursor_path: Option<String>,
        /// Alternatively, a field of the last record (e.g. `id` for `starting_after`).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        last_record_field: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size_param: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size: Option<u32>,
    },
    /// The body holds the full URL of the next page.
    NextUrl { next_path: String },
    /// Follow the `Link: <…>; rel="next"` header only.
    LinkHeader,
}

fn one() -> u64 {
    1
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Incremental {
    /// Record field holding the last-modified value (dotted path for nested fields).
    pub cursor: String,
    /// Server-side filter parameter: the next run sends `param=<watermark>`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub param: Option<String>,
    /// Descending sort on the cursor, for client-side early stop.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sort: Option<Sort>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Sort {
    pub param: String,
    pub value: String,
    /// Extra parameters, such as `direction = "desc"`.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub params: BTreeMap<String, String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    Filter,
    EarlyStop,
    FullRefresh,
}

impl Mode {
    pub fn label(self) -> &'static str {
        match self {
            Mode::Filter => "filter",
            Mode::EarlyStop => "early stop",
            Mode::FullRefresh => "full refresh",
        }
    }
}

impl StreamConfig {
    pub fn mode(&self) -> Mode {
        match &self.incremental {
            Some(Incremental { param: Some(_), .. }) => Mode::Filter,
            Some(Incremental { sort: Some(_), .. }) => Mode::EarlyStop,
            _ => Mode::FullRefresh,
        }
    }

    pub fn cursor(&self) -> Option<&str> {
        self.incremental.as_ref().map(|i| i.cursor.as_str())
    }
}

fn ser_key<S: Serializer>(key: &[String], s: S) -> Result<S::Ok, S::Error> {
    if key.len() == 1 {
        key[0].serialize(s)
    } else {
        key.serialize(s)
    }
}

fn de_key<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<String>, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Key {
        One(String),
        Many(Vec<String>),
    }
    Ok(match Key::deserialize(d)? {
        Key::One(k) => vec![k],
        Key::Many(ks) => ks,
    })
}

pub mod duration_str {
    use std::time::Duration;

    use serde::{Deserialize, Deserializer, Serializer, de::Error};

    pub fn serialize<S: Serializer>(d: &Duration, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&humantime::format_duration(*d).to_string())
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Duration, D::Error> {
        let s = String::deserialize(d)?;
        humantime::parse_duration(&s)
            .map_err(|e| D::Error::custom(format!("invalid duration {s:?}: {e}")))
    }
}

pub mod bytes_str {
    use serde::{Deserialize, Deserializer, Serializer, de::Error};

    pub fn serialize<S: Serializer>(b: &u64, s: S) -> Result<S::Ok, S::Error> {
        let units = [("GiB", 1u64 << 30), ("MiB", 1 << 20), ("KiB", 1 << 10)];
        let text = units
            .iter()
            .find(|(_, size)| *b >= *size && b.is_multiple_of(*size))
            .map(|(unit, size)| format!("{}{unit}", b / size))
            .unwrap_or_else(|| format!("{b}B"));
        s.serialize_str(&text)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<u64, D::Error> {
        let s = String::deserialize(d)?;
        s.parse::<bytesize::ByteSize>()
            .map(|b| b.as_u64())
            .map_err(|e| D::Error::custom(format!("invalid size {s:?}: {e}")))
    }
}

/// Replaces every `${VAR}` with the value of `VAR` from the environment
/// (which includes `.env`, loaded at startup). A missing or empty variable is an error.
pub fn interpolate(s: &str) -> anyhow::Result<String> {
    static VAR: std::sync::LazyLock<regex::Regex> =
        std::sync::LazyLock::new(|| regex::Regex::new(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}").unwrap());
    let mut missing = Vec::new();
    let out = VAR.replace_all(s, |c: &regex::Captures| match std::env::var(&c[1]) {
        Ok(v) if !v.is_empty() => v,
        _ => {
            missing.push(c[1].to_string());
            String::new()
        }
    });
    if !missing.is_empty() {
        anyhow::bail!(
            "{} not set: fill in {} in .env",
            if missing.len() == 1 {
                "variable is"
            } else {
                "variables are"
            },
            missing.join(", ")
        );
    }
    Ok(out.into_owned())
}

/// Variable names referenced as `${VAR}` in a string.
pub fn referenced_vars(s: &str) -> Vec<String> {
    let re = regex::Regex::new(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}").unwrap();
    re.captures_iter(s).map(|c| c[1].to_string()).collect()
}

impl Config {
    pub fn parse(text: &str) -> anyhow::Result<Config> {
        let config: Config = toml::from_str(text)?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> anyhow::Result<()> {
        let mut seen = std::collections::BTreeSet::new();
        for s in &self.streams {
            if !seen.insert(&s.name) {
                anyhow::bail!("stream `{}` is defined twice", s.name);
            }
            // The name lands in a DuckDB glob path, so `*`, `?` or `[` would read other streams.
            if s.name.is_empty()
                || !s
                    .name
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
            {
                anyhow::bail!(
                    "invalid stream name {:?}: use letters, digits, `_` or `-`",
                    s.name
                );
            }
            if s.incremental.is_some() && s.primary_key.is_empty() {
                // Allowed, but the generated views need a key to deduplicate.
                tracing::debug!("stream {} has a cursor but no primary key", s.name);
            }
        }
        if self.source.concurrency == 0 {
            anyhow::bail!("source.concurrency must be at least 1");
        }
        if self.source.retry.max_tries == 0 {
            anyhow::bail!("source.retry.max_tries must be at least 1");
        }
        Ok(())
    }

    /// Renders the config as TOML, with small tables inline and optional
    /// comments: a header, a note per stream, and a note before `[destination]`.
    pub fn render(
        &self,
        header: &str,
        notes: &BTreeMap<String, String>,
        source_note: Option<&str>,
    ) -> String {
        use toml_edit::{DocumentMut, Item, Value};
        let text = toml::to_string(self).expect("config serializes");
        let mut doc: DocumentMut = text.parse().expect("toml output parses");

        fn inline(table: &mut toml_edit::Table, keys: &[&str]) {
            for key in keys {
                if let Some(item) = table.get_mut(key)
                    && let Item::Table(t) = item
                {
                    let t = std::mem::take(t);
                    *item = Item::Value(Value::InlineTable(t.into_inline_table()));
                    if let Some(mut k) = table.key_mut(key) {
                        k.leaf_decor_mut().set_suffix(" ");
                    }
                }
            }
            // Keep struct order: scalars and inlined tables interleaved as declared.
            let order: Vec<String> = ORDER.iter().map(|s| s.to_string()).collect();
            table.sort_values_by(|a, _, b, _| {
                let rank = |k: &str| order.iter().position(|o| o == k).unwrap_or(usize::MAX);
                rank(a.get()).cmp(&rank(b.get()))
            });
        }
        const ORDER: [&str; 20] = [
            "spec",
            "base_url",
            "auth",
            "rate_limit",
            "retry",
            "concurrency",
            "headers",
            "url",
            "format",
            "rotate",
            "endpoint",
            "region",
            "name",
            "path",
            "enabled",
            "records",
            "primary_key",
            "params",
            "pagination",
            "incremental",
        ];
        if let Some(source) = doc.get_mut("source").and_then(Item::as_table_mut) {
            inline(source, &["auth", "rate_limit", "retry", "headers"]);
        }
        if let Some(dest) = doc.get_mut("destination").and_then(Item::as_table_mut) {
            inline(dest, &["rotate"]);
            if let Some(note) = source_note {
                dest.decor_mut().set_prefix(format!("{note}\n\n"));
            }
        }
        if let Some(streams) = doc
            .get_mut("streams")
            .and_then(Item::as_array_of_tables_mut)
        {
            for t in streams.iter_mut() {
                inline(t, &["params", "pagination", "incremental"]);
                let name = t
                    .get("name")
                    .and_then(Item::as_str)
                    .unwrap_or_default()
                    .to_string();
                if let Some(note) = notes.get(&name) {
                    t.decor_mut().set_prefix(format!("\n{note}\n"));
                }
            }
        }
        let body = doc.to_string();
        if header.is_empty() {
            body
        } else {
            format!("{header}\n\n{body}")
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Config {
        Config::parse(
            r#"
[source]
spec = "openapi.yaml"
base_url = "https://api.example.test"
auth = { type = "bearer", token = "${EXAMPLE_TOKEN}" }
rate_limit = { max_calls = 100, period = "1m" }

[destination]
format = "parquet"
rotate = { max_bytes = "64MiB" }

[[streams]]
name = "users"
path = "/users"
records = "/data"
primary_key = "id"
pagination = { type = "page_number", param = "page", size_param = "per_page", size = 100 }
incremental = { cursor = "updated_at", sort = { param = "sort", value = "-updated_at" } }
"#,
        )
        .unwrap()
    }

    #[test]
    fn parses_with_defaults() {
        let c = sample();
        assert_eq!(c.destination.url, "file://data");
        assert_eq!(c.destination.rotate.max_bytes, 64 << 20);
        assert_eq!(c.source.retry, RetryConfig::default());
        assert_eq!(
            c.source.rate_limit.as_ref().unwrap().period,
            Duration::from_secs(60)
        );
        assert_eq!(c.streams[0].primary_key, ["id"]);
        assert_eq!(c.streams[0].mode(), Mode::EarlyStop);
        assert!(c.streams[0].enabled);
    }

    #[test]
    fn render_round_trips_and_inlines() {
        let c = sample();
        let notes = BTreeMap::from([("users".to_string(), "# users: early stop".to_string())]);
        let text = c.render("# header", &notes, Some("# no rate limit"));
        assert!(text.starts_with("# header"));
        assert!(text.contains("auth = { type = \"bearer\""), "{text}");
        assert!(
            text.contains("pagination = { type = \"page_number\""),
            "{text}"
        );
        assert!(text.contains("# users: early stop\n[[streams]]"), "{text}");
        assert!(text.contains("max_bytes = \"64MiB\""), "{text}");
        assert_eq!(Config::parse(&text).unwrap(), c);
    }

    #[test]
    fn rejects_unknown_fields_and_duplicates() {
        assert!(
            Config::parse("[source]\nspec='a'\nbase_url='b'\ntypo=1\n[destination]\n").is_err()
        );
        let dup = "[source]\nspec='a'\nbase_url='b'\n[destination]\n[[streams]]\nname='a'\npath='/a'\n[[streams]]\nname='a'\npath='/b'\n";
        assert!(
            Config::parse(dup)
                .unwrap_err()
                .to_string()
                .contains("twice")
        );
    }

    #[test]
    fn stream_names_allow_only_letters_digits_underscore_dash() {
        let parse = |name: &str| {
            Config::parse(&format!(
                "[source]\nspec='a'\nbase_url='b'\n[destination]\n[[streams]]\nname='{name}'\npath='/a'\n"
            ))
        };
        for ok in ["users", "user_events", "user-events", "Users2"] {
            assert!(parse(ok).is_ok(), "{ok}");
        }
        for bad in ["", "user*", "a b", "a?", "a[b]", "a/b", "a.b", "é"] {
            let err = parse(bad).unwrap_err().to_string();
            assert!(err.contains("invalid stream name"), "{bad}: {err}");
        }
    }

    #[test]
    fn interpolation() {
        // SAFETY: test-only, single variable owned by this test.
        unsafe { std::env::set_var("APISIP_TEST_INTERP", "s3cr3t") };
        assert_eq!(
            interpolate("Bearer ${APISIP_TEST_INTERP}").unwrap(),
            "Bearer s3cr3t"
        );
        let err = interpolate("${APISIP_TEST_MISSING_ONE}")
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("APISIP_TEST_MISSING_ONE") && err.contains(".env"),
            "{err}"
        );
        assert_eq!(referenced_vars("${A}:${B_2}"), ["A", "B_2"]);
    }
}
